#include "ark/onboarding.hpp"
#include <stdexcept>
namespace ark {
arkjson::Value agentOnboard(const AgentSession& session,const arkjson::Value& args){
    using V=arkjson::Value;std::string topic="overview";
    if(auto p=args.find("topic")){if(p->t!=V::Str)throw std::runtime_error("topic must be a string");topic=p->str;}
    if(topic!="overview"&&topic!="sketch"&&topic!="tube"&&topic!="assembly")throw std::runtime_error("Unknown onboarding topic; choose overview, sketch, tube or assembly");
    V r=V::makeObj();r.set("product",V::makeStr("ARK"));r.set("name",V::makeStr("Agent-Ready Kernel"));r.set("tagline",V::makeStr("Parametric CAD for people and agents."));r.set("version",V::makeStr("0.7.0"));r.set("topic",V::makeStr(topic));r.set("document",session.info());
    r.set("units",V::makeStr("Lengths mm; plane/feature rotations degrees; sketch angle constraints and trig radians. deg(x) converts degrees to radians."));
    auto list=[](std::initializer_list<const char*> strings){V a=V::makeArr();for(auto s:strings)a.arr.push_back(V::makeStr(s));return a;};
    r.set("workflow",list({"Read this onboarding then doc_get only when detailed parameters/features are needed.","Use doc_apply with expected_revision. One batch recomputes once; any failure rolls back the entire batch.","Use created_ids returned by a batch for later feature inputs. Do not assume IDs or use triangle IDs as persistent references.","Inspect measured results using sketch_inspect, mesh_inspect, mesh_raycast or source_inspect. A successful operation alone is not manufacturing certification.","Keep queries compact; request sampled curves, meshes or snapshots only when needed. Save the parametric document with doc_save."}));
    r.set("available_topics",list({"overview","sketch","tube","assembly"}));
    r.set("boundaries",list({"Sketch extrusions and through-cuts use sampled profiles. Interior through-cuts in extrusions validate cap area, closed topology and volume. Other cuts use mesh CSG and reject invalid topology. General exact B-rep STEP export is not implemented.","Source STEP tubes are source-preserving/read-only and supported only for the documented planar retained-wall finite-hinge domain.","No persistent face/edge naming, automatic arbitrary STEP feature-history reconstruction, global sketch uniqueness proof or assembly mate solver.","GPU acceleration applies to packed transforms/display, not every CAD operation. Scientific checks have explicit numerical/model limits."}));
    r.set("capabilities",list({"Named parameters and expression dependencies","Named construction planes with parent frames","Dimensioned sketches: points, lines, circles, interpolating splines","Extrude, revolve, sketch_cut, primitives, mesh booleans, expression surfaces","Rigid assemblies and tube bend programs","Validated bounded source STEP unfolding and straight export","Atomic edits, undo/redo, native document persistence, mesh inspection"}));
    if(topic=="sketch"){
        r.set("tools",list({"doc_apply","plane_inspect","sketch_inspect","mesh_inspect","mesh_raycast","snapshot","doc_save"}));
        r.set("rules",list({"plane.set{name,parent,p:{ox,oy,oz,rx,ry,rz}} creates/updates a named frame. Built-in XY/XZ/YZ cannot be changed. XZ normal=-Y, YZ normal=+X.","sketch.set{name,sketch:{plane,tolerance,entities,constraints}} replaces a sketch. Names identify sketches and entities; changing a referenced name is not an automatic rename.","Entity kind is point|line|circle|spline. dof is [x,y], [x0,y0,x1,y1], [cx,cy,r] or flattened spline anchors. construction:true excludes an entity from solid profiles.","A string coordinate such as 'width/2' is driven exactly by that expression. A numeric coordinate is a free solver variable/initial position. Constraint val/val2 accept numeric values or expressions.","Spline: 2..64 anchors (closed minimum 3), closed:true wraps without repeating first anchor; tension 0..1. Centripetal Catmull-Rom converted to cubic Bezier and adaptively sampled. tolerance is curve-to-chord approximation in mm, not manufacturing accuracy.","sketch.entity.set{name,entity:{name,kind,dof,...}} replaces/appends one named entity. Unchanged entities and constraint indexes stay in place. Use it to avoid resending an entire sketch.","Constraint types: fixedX, fixedY, fixed, distance, horizontal, vertical, parallel, perpendicular, radius, coincident, angle. a/b index entities; pa/pb index line endpoints or spline anchors; circle slot0=center.","Extrude/revolve consumes one closed outer loop via p.sketch. sketch_cut consumes one base feature in inputs and one sketch of disjoint closed loops, with p.depth positive and p.offset along local normal.","Open curves can be saved/inspected but cannot form a solid until explicitly closed. Self-crossing/touching sampled profiles, nested loops and ambiguous joins are rejected.","sketch_inspect reports resolved coordinates, remaining_dofs, local Jacobian rank and profile_ready. Underconstrained does not mean failed. samples:true adds local/world polylines.","Limits: 64 sketches, 128 entities and 256 constraints per sketch, 512 scalar coordinates, 2048 samples per curve/loop and 4096 per profile collection. Tolerance 0.0001..5 mm."}));
        V example;arkjson::parse(R"({"commands":[{"op":"param.set","name":"width","expr":"100"},{"op":"param.set","name":"height","expr":"45"},{"op":"plane.set","name":"design","parent":"XY","p":{"oz":"8","rx":"15"}},{"op":"sketch.set","name":"outline","sketch":{"plane":"design","tolerance":0.03,"entities":[{"name":"skin","kind":"spline","closed":true,"dof":["-width/2","0","-width/3","-height/2","width/3","-height/2","width/2","0","width/3","height/2","-width/3","height/2"]}]}},{"op":"feature.add","type":"extrude","name":"Freeform plate","p":{"sketch":"outline","height":"6"}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("After this example, inspect outline, then change width with param.set. To cut holes, create a circle sketch on design and sketch_cut with the returned extrusion ID, depth='8', offset='-1'."));
    }else if(topic=="tube"){
        r.set("tools",list({"import_step","source_inspect","notch_plan","notch_inspect","tube_inspect","export_step"}));
        r.set("rules",list({"import_step{path,replace:false} adds a supported source tube without replacing the current document. replace:true replaces it. Source stays read-only.","source_inspect{id,progress} reads source/flat openings and evidence; progress 0..1 is display only. Export STEP is always straight.","Designed notched_tube uses dimensions width_mm,height_mm,wall_mm,length_mm,hinge_offset_mm plus notches:[{station,angle,face}]. This ideal model differs from finite source hinges.","Tube programs use round/rect sections and bends [{feed,radius,angle,roll}]. Tube program previews and imported-source validation have different guarantees.","Use existing source geometry as the authority for hole locations. Never infer missing source features from a screenshot or silently invent unsupported deformation."}));
    }else if(topic=="assembly"){
        r.set("tools",list({"doc_apply","assembly_info","mesh_inspect","mesh_raycast"}));
        r.set("rules",list({"assembly.add{name,parent,feature,p,visible}: parent=0 root, feature=0 group, otherwise existing feature ID.","p is rigid tx/ty/tz/rx/ry/rz expressions relative to parent. Shared feature definitions produce instances, not duplicated geometry.","Use assembly_info for world transforms and BOM quantities. There are no automatic mates or collision certification.","Mesh queries accept node for an instance or id for a part definition; do not provide both."}));
    }else r.set("next_step",V::makeStr("Choose a targeted onboarding topic. For a new parametric part begin with topic='sketch'; for original tube STEP use topic='tube'. No language model is required for deterministic geometry operations."));
    return r;
}
}
